/* Animations */
@keyframes rainbow {
  0% { background-position-x: 0% }
  100% { background-position-x: 100% }
}
@keyframes phase-blink {
  15% { opacity: 1 }
  50% { opacity: 0 }
  85% { opacity: 1 }
}

/* Colors and Fonts */
:root {
  /* Animation Timings */
  --anim-duration-none: 0;
  --anim-duration-superfast: 75ms;
  --anim-duration-fast: 150ms;
  --anim-duration-moderate: 250ms;
  --anim-duration-slow: 500ms;

  /* Custom Colors */
	--day0:        15, 20%, 96%;
