/*Box Sizing Reset - this makes it easier to set any ::before and ::after pseudo-elements' dimensions,
since it includes any border and padding into the height and width values you set.
*,
*::before,
*::after {
box-sizing: border-box;
}*/

/*----Progress Bar Screen----*/
/*Progress Bar Window*/
.progress-bar {
  background-color: hsl(var(--color-base-1));
}

/*Progress Bar Background*/
.progress-bar-line {
  background-color: hsl(var(--color-base-3));
  border-radius: 50px;
}

/*Progress Bar Loaded*/
.progress-bar-subline {
  background-image: repeating-linear-gradient(90deg,
    hsl(var(--color-pink)) 5%, hsl(var(--color-red)) 15%, hsl(var(--color-orange)) 25%,
    hsl(var(--color-yellow)) 35%, hsl(var(--color-green)) 45%, hsl(var(--color-teal)) 55%,
    hsl(var(--color-blue)) 65%, hsl(var(--color-cyan)) 75%, hsl(var(--color-purple)) 85%,
    hsl(var(--color-pink)) 95%);
  background-size: 1000% 100%;
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: content-box;
  animation: rainbow 1s linear infinite;
}

/*Progress Text*/
.progress-bar .progress-bar-message {
  background-image: repeating-linear-gradient(90deg, 
  hsl(var(--color-pink)) 5%, hsl(var(--color-red)) 15%, hsl(var(--color-orange)) 25%, 
  hsl(var(--color-yellow)) 35%, hsl(var(--color-green)) 45%, hsl(var(--color-teal)) 55%, 
  hsl(var(--color-blue)) 65%, hsl(var(--color-cyan)) 75%, hsl(var(--color-purple)) 85%, 
  hsl(var(--color-pink)) 95%);
  background-size: 1000% 100%;
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: text;
  animation: rainbow 1s linear infinite;
  border-radius: 50px;
}

/*----Settings----*/
/*All Popup Windows: Settings*/
.modal {
  color: hsl(var(--color-text-normal));
  background-color: hsl(var(--color-base-2));
  border-color: hsl(var(--color-interactable)) !important;
}

/*Command Palette & Quick Switcher*/
.prompt {
  color: hsl(var(--color-text-normal));
  background-color: hsl(var(--color-base-3));
}
.style-solar .prompt {
  background-color: hsl(var(--color-base-0));
}

/*The notifications in the top right*/
.notice {
  background-color: hsl(var(--color-base-3));
  color: hsl(var(--color-caution));
  border: solid 1px hsl(var(--color-caution));
}
.style-solar .notice {
  background-color: hsl(var(--color-base-2));
}

/*Context Menu (Right Clicks)*/
.menu {
  background-color: hsl(var(--color-base-3));
  border-color: hsl(var(--color-interactable));
}
.style-solar .menu {
  background-color: hsl(var(--color-base-2));
}

.mod-warning {
  font-weight: var(--weight-maxbold);
}

/*Toggles*/
.checkbox-container {
  background-color: hsl(var(--color-interactable));
}
.checkbox-container:hover {
  background-color: hsl(var(--color-hovered));
}
.checkbox-container.is-enabled {
  background-color: hsl(var(--color-confirmed));
}
.checkbox-container::after {
  background-color: hsl(var(--color-base-1));
}

/*Dropdown*/
.dropdown, .dropdown option {
  color: hsl(var(--color-interactable)) !important;
  background-color: hsl(var(--color-base-3)) !important;
  font-weight: var(--weight-bold) !important;
  box-shadow: none !important;
}
.style-solar .dropdown, .style-solar .dropdown option {
  color: hsl(var(--color-interactable)) !important;
  background-color: hsl(var(--color-base-2)) !important;
}

/*Dropdown Hover*/
.dropdown:hover, button:not(.clickable-icon):hover{
  color: hsl(var(--color-text-highlight)) !important;
  background-color: hsl(var(--color-hovered)) !important;
  font-weight: var(--weight-bold) !important;
}

/*Dropdown Focus*/
.dropdown:focus {
  box-shadow: none;
}

/*Sliders*/
input[type='range'] {
  width: 100px;
  -webkit-appearance: none;
  background-color: hsl(var(--color-alternate));
  border-radius: 3px;
  height: 3px;
  padding: 0;
}

/*Slider Knobs*/
input[type='range' i] {
  color: magenta;
}

/*Text Inputs*/
textarea, input[type='text'], 
input[type='search'], input[type='email'], 
input[type='password'], input[type='number'] {
  background: hsl(var(--color-base-2));
}
input[type='search']:hover {
  box-shadow: none !important;
  border-color: hsl(var(--color-hovered));
}
input[type='search']:focus {
  box-shadow: none !important;
  border-color: hsl(var(--color-alternate));
}

/*Choices*/
.choices__inner,
.choices__list--dropdown {
  background: hsl(var(--color-base-3)) !important;
}

/* ------Community Content--- */
.community-item .suggestion-highlight {
  color: hsl(var(--color-text-highlight));
}

.community-item:hover {
  --background-modifier-border-hover: hsl(var(--color-interactable));
}

.community-item.is-selected,
.community-item.is-selected:hover {
  --interactive-accent: hsl(var(--color-hovered));
}


/*--Extras--*/
/*Tooltip Popup*/
.tooltip {
  background-color: hsl(var(--color-base-3));
  color: hsl(var(--color-interactable));
  border: solid 1px hsl(var(--color-alternate));
}
.style-solar .tooltip {
  background-color: hsl(var(--color-base-2));
}
.tooltip .mod-error {
  background-color: hsl(var(--color-base-3));
  color: hsl(var(--color-stop));
  border: solid 1px hsl(var(--color-stop));
}
.style-solar .tooltip .mod-error {
  background-color: hsl(var(--color-base-2));
  color: hsl(var(--color-stop));
  border: solid 1px hsl(var(--color-stop));
}
.tooltip .tooltip-arrow,
.tooltip.mod-right .tooltip-arrow,
.tooltip.mod-left .tooltip-arrow,
.tooltip.mod-top .tooltip-arrow {
  background-color: transparent;
  color: transparent;
  border: transparent;
  content: " ";
}
.tooltip.mod-error .tooltip-arrow,
.tooltip.mod-error.mod-right .tooltip-arrow,
.tooltip.mod-error.mod-left .tooltip-arrow,
.tooltip.mod-error.mod-top .tooltip-arrow {
  background-color: transparent;
  color: transparent;
  border: transparent;
  content: " ";
}

/*--File Explorer--*/
/*Nav Top: Create Note, Sort, Create Folder*/
.nav-header {
  border-style:solid;
  border-radius: 5px;
  border-color: transparent;
}

/*Folder*/
.nav-folder {
  border-style:solid;
  border-radius: 5px;
  border-color: transparent;
  font-weight: var(--weight-maxbold);
}

/* Indentation Lines (ALL NAVIGATION LISTS) (left border) */
.nav-folder.mod-root .nav-folder > .nav-folder-children,
.tree-item-children {
  border-color: hsl(var(--color-text-faint));
  border-bottom-left-radius: 1%;
  padding-left: 1em;
  margin-left: .5%;
}
.markdown-rendered ul,
.markdown-rendered ol {
  border-color: hsl(var(--color-text-faint));
  border-bottom-left-radius: 1%;
  padding-left: 2em;
  margin-left: none;
}

/*Dragging files into folders*/
.nav-folder.is-being-dragged-over {
  background: hsla(var(--color-hovered), 0.1);
}

/* Nav Title / Vault Name */
.nav-folder-title:hover,
.nav-folder.mod-root > .nav-folder-title:hover {
  background-image: repeating-linear-gradient(90deg, 
 hsl(var(--color-pink)) 5%,hsl(var(--color-red)) 15%,hsl(var(--color-orange)) 25%, 
 hsl(var(--color-yellow)) 35%,hsl(var(--color-green)) 45%,hsl(var(--color-teal)) 55%, 
 hsl(var(--color-blue)) 65%,hsl(var(--color-cyan)) 75%,hsl(var(--color-purple)) 85%, 
 hsl(var(--color-pink)) 95%);
  background-size: 1000% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: rainbow 12s linear infinite;
  font-weight: var(--weight-maxbold);
}

/* Active file/folder */
.nav-file-title.is-active,
.nav-folder-title.is-active {
  color: hsl(var(--color-selected));
  background-color: hsl(var(--color-base-0));
}

/* File Navigator Folder Names */
.nav-folder-title-content {
  color: hsl(var(--color-text-normal));
  font-weight: var(--weight-bold);
}

/* File Navigator Files */
.tree-item-self {
  margin-left: 12px !important;
  padding-left: 14px !important;
}
:not(.is-grabbing) .nav-file-title:hover,
:not(.is-grabbing) .nav-folder-title:hover,
.tree-item-self.is-clickable:hover {
  background-color: hsl(var(--color-base-1));
}

/*File Extension Label*/
.nav-file-tag,
.nav-file-tag:hover {
  background-color: transparent;
  color: hsl(var(--color-content));
  font-weight: var(--weight-extrabold);
}

/* Folder Icons */
.nav-folder-collapse-indicator,
.nav-folder.mod-root > .nav-folder-title .nav-folder-title-content::before {
  display: none;
}
.sQdthOne-hide-folder-icons 
.nav-folder-title-content {
  margin-left: -15px !important;
  padding-left: 0px !important;
}

/* Closed Folder Icons */
.nav-folder.is-collapsed .nav-folder-title .nav-folder-title-content::before {
