/* Normal Text */
body {
  /* Generic things */
  --background-modifier-cover: rgba(0, 0, 0, 0.8); /*Obsidian Title Bar Bg*/
  --background-primary: hsl(var(--color-base-1)); /*Note background*/
  --background-primary-alt: hsl(var(--color-base-0)); /*Note Title background active*/
  --background-secondary: hsl(var(--color-base-2)); /*Sidebar background*/
  --background-secondary-alt: hsl(var(--color-base-1)); /*Sidebar Title background*/
  --background-modifier-border: hsl(var(--color-interactable)); /*Border outline of quotes, tables, line breaks*/
  --text-normal: hsl(var(--color-text-normal)); /*Text body of note*/
  --text-muted: hsl(var(--color-text-muted)); /*Text darker for sidebar, toggles, inactive, tags, etc*/
  --text-accent: hsl(var(--color-interactable)); /*Links*/
  --text-accent-hover: hsl(var(--color-hovered)); /*Links hover*/
  --text-faint: hsl(var(--color-text-faint)); /*Link brackets color & Gutter Numbers*/
  --text-highlight-bg: hsl(var(--color-text-highlight-background)); /*Search Matches*/
  --text-highlight-bg-active: hsl(var(--color-text-highlight-active-background)); /*Active Search Match (Preview Mode)*/
  --scrollbar-active-thumb-bg: hsl(var(--color-hovered)); /*Scrollbar Dragged Color*/
  --interactive-accent: hsl(var(--color-interactable)) !important; /*Default for most interactables*/
  --interactive-normal: hsl(var(--color-base-3)); /*Button Color*/
  --interactive-hover: hsl(var(--color-hovered)); /*Button Hovered Color*/
  --interactive-accent: var(--text-accent); /*Workspace Note Title Underline*/
  --interactive-accent-hover: hsl(var(--color-hovered)); /*Menu Button Hover*/
  --slider-track-background: hsl(var(--color-interactable)); /*Settings Slider Backgrounds*/
}

/*Selected*/
select:focus {
  box-shadow: none;
}

/*Selected Text*/
::selection, /*Reading mode*/
.cm-s-obsidian .CodeMirror-selected {
  color: hsl(var(--color-text-highlight)) !important;
  background-color: hsl(var(--color-text-highlight-background)) !important;
}

/* Outline List */
.tree-item-self.is-active {
  background-color: hsl(var(--color-base-0));
  border: solid 1px hsl(var(--color-base-2));
}

/*--Horizontal Line--*/
/*Reading Mode*/
hr {
  color: hsl(var(--color-horizontal-rule));
} 
/*Source Mode*/
.hr.cm-line {
  color: hsl(var(--color-horizontal-rule));
} 
/*Source Mode*/
.HyperMD-hr-bg,
.cm-s-obsidian pre.HyperMD-hr {
  color: hsl(var(--color-horizontal-rule));
} 

/*--Comments--*/
/* html comments and obsidian style comments */
.cm-comment {
  color: hsl(var(--color-base-5));
}

/*--Frontmatter/Metadata/Yaml--*/
/*Reading Mode*/
.frontmatter-container {
  color: hsl(var(--color-base-5));
} 
/*Source Mode*/
.CodeMirror-line .cm-s-obsidian .cm-hmd-frontmatter,
.cm-meta {
  color: hsl(var(--color-base-5));
} 
/*Frontmatter Tag*/
/*Reading Mode*/
.frontmatter-container .frontmatter-alias {
  color: hsl(var(--color-base-5));
} 

/*--Code--*/
/* Edit mode */
.cm-s-obsidian pre.HyperMD-codeblock {     
  font-family: var(--font-monospace);
  font-weight: var(--weight-light);
}

/* Preview mode */
.markdown-preview-view code {
  font-family: var(--font-monospace);
  font-weight: var(--weight-light);
}

/*--Lists--*/
.markdown-source-view ol > li,
.markdown-source-view ul > li,
.markdown-preview-view ol > li,
.markdown-preview-view ul > li,
.markdown-rendered ul > li,
.mod-cm6 .HyperMD-list-line.cm-line {
  padding-top: 0;
  padding-bottom: 0;
}

.markdown-rendered.show-indentation-guide li > ul::before,
.markdown-rendered.show-indentation-guide li > ol::before {
  width: auto;
}

.list-item-part.clickable-icon:hover,
.list-item-part.clickable-icon:active {
  background-color: hsl(var(--color-hovered));
}

/* Check Lists */
body:not(.sQdthOne-disable-alternative-checkboxes) input.task-list-item-checkbox {
  border-style: solid;
  border-color: hsl(var(--color-alternate));
  border-width: 1px;
  border-radius: 5px;
  background-color: transparent;
  transition: var(--anim-duration-moderate);
}
body:not(.sQdthOne-disable-alternative-checkboxes) input.task-list-item-checkbox:hover {
  border-style: solid;
  border-color: hsl(var(--color-hovered));
  border-width: 5px;
  border-radius: 100%;
  background-color: transparent;
  transition: var(--anim-duration-moderate);
}
body:not(.sQdthOne-disable-alternative-checkboxes) input.task-list-item-checkbox:checked:hover {
  border-style: double;
