/*--Blockquotes--*/
/* Read view */
.markdown-rendered blockquote,
.markdown-preview-view blockquote {
  font-weight: var(--weight-extralight);
  color: hsl(var(--color-caution));
  background-color: hsl(var(--color-caution), 10%);
  border-color: hsl(var(--color-caution));
  border-radius: 5px;
  border-width: 5px;
}
.markdown-source-view.mod-cm6.is-live-preview .HyperMD-quote:before, 
.markdown-source-view.mod-cm6 .cm-blockquote-border:before {
  color: hsl(var(--color-caution));
  border-left: var(--blockquote-border-thickness) solid hsl(var(--color-caution));
}
/* Edit view */
.cm-s-obsidian span.cm-quote {
  font-weight: var(--weight-extralight);
  color: hsl(var(--color-caution));
  background-color: transparent;
}

/*--Tables--*/
/*Table*/
table,
.markdown-rendered table {
  border-collapse: separate;
  border: solid 3px hsl(var(--color-caution));
  border-radius: 6px;
  border-spacing: 0px;
}

/*Even Count Table Rows*/
tbody > tr:nth-child(even) {
  background-color: hsl(var(--color-base-2)) !important;
}

/*Table Body*/
tbody > tr {
  background-color: hsl(var(--color-base-2));
}

/*Table Header*/
th, thead,
.markdown-rendered th {
  padding: 5px 20px;
  border: none;
  border-right: 1px solid hsl(var(--color-content)) !important;
  border-bottom: 1px solid hsl(var(--color-content)) !important;
  color: hsl(var(--color-text-normal));
  background-color: hsl(var(--color-base-3)) !important;
} 
.style-solar th, .style-solar thead,
.style-solar .markdown-rendered th {
  background-color: hsl(var(--color-base-2)) !important;
}

/*Left Most Header*/
th:first-child, thead:first-child,
.markdown-rendered th:first-child {
  border-left: none !important;
}

/*Right Most Header*/
th:last-child, thead:last-child,
.markdown-rendered th:last-child {
  border-right: none !important;
}

/*Table Data as Col*/
td,
.markdown-rendered td {
  padding: 5px 20px;
  border: none;
  border-right: 1px solid;
  color: hsl(var(--color-text-normal));
  border-color: hsl(var(--color-base-3));
}

/*First Col of Table Data*/
td:first-child,
.markdown-rendered td:first-child {
  border-left: none;
}

/*Last Col of Table Data*/
td:last-child,
.markdown-rendered td:last-child {
  border-right: none;
}

/*--Tags--*/
/*Reading*/
.multi-select-pill,
a.tag,
.tag {
	border: none;
  color: hsl(var(--color-base-1));
	background-color: hsl(var(--color-caution));
  font-weight: var(--weight-medium);
	padding: auto;
	text-align: center;
	text-decoration: none;
	margin: auto;
	border-radius: 25px;
  transition: var(--anim-duration-moderate);
}
.multi-select-pill:hover,
a.tag:hover,
.tag:hover {
  border-style: solid;
  border-width: 0px;
	border-color: transparent;
  color: hsl(var(--color-text-highlight));
	background-color: hsl(var(--color-hovered));
  font-weight: var(--weight-medium);
  padding: auto;
	text-align: center;
	text-decoration: none;
	margin: auto;
	border-radius: 5px;
  transition: var(--anim-duration-moderate);
}
.multi-select-pill:hover .multi-select-pill-remove-button,
a.tag:hover .multi-select-pill-remove-button,
.tag:hover .multi-select-pill-remove-button {
  color: hsl(var(--color-text-highlight));
}

/*Live Preview + Source*/
  /*Left*/
.cm-s-obsidian span.cm-hashtag-begin {
  border: none;
  color: hsl(var(--color-base-1));
	background-color: hsl(var(--color-caution));
	padding: auto;
	text-align: center;
	text-decoration: none;
	margin: auto;
