  transition: var(--anim-duration-moderate);
}
  /*Right*/
.cm-s-obsidian span.cm-hashtag-end {
  border: none;
  color: hsl(var(--color-base-1));
	background-color: hsl(var(--color-caution));
	padding: auto;
	text-align: center;
	text-decoration: none;
	margin: auto;
  border-top-right-radius: 25px ;
