/*-----Graph View-----*/
/*color of nodes*/
.graph-view.color-fill {
	color: hsl(var(--color-cyan));
}
/*color of focused node/note*/
.graph-view.color-fill-focused { 
  color: hsl(var(--color-text-highlight-active-background));
}
/*focused node border color*/
.graph-view.color-circle {
	color: transparent;
}
/*link color*/
.graph-view.color-line {
	color: hsl(var(--color-base-3));
}
/*text color*/
.graph-view.color-text {
	color: hsl(var(--color-text-normal));
}
/*focused node color*/
.graph-view.color-fill-highlight {
	color: hsl(var(--color-hovered));
}
/*focused node connections*/
.graph-view.color-line-highlight {
  color: hsl(var(--color-base-5));
}
/*Tag node color*/
.graph-view.color-fill-tag {
  color: hsl(var(--color-tag));
}
/*Attachment node color*/
.graph-view.color-fill-attachment {
  color: hsl(var(--color-content));
}
/*Unresolved (not created yet) notes*/
.graph-view.color-fill-unresolved {
  color: hsl(var(--color-stop));
  opacity: 0.5;
}
/*arrow color*/
.graph-view.color-arrow {
  color: hsl(var(--color-text-faint));
  opacity: 0.5;
}
/*Graph Menu*/
.graph-controls {} 

/*------Canvas------*/
/*Canvas Card Menus*/
.canvas-card-menu {
  background-color: hsl(var(--color-base-2)) !important;
}

/*Indicates item selected/focused*/
.canvas-node.is-selected .canvas-node-label,
.canvas-node.is-focused .canvas-node-label {
  color: hsl(var(--color-selected));
}

