/*--Calendar--*/
/*Calendar Grid Container*/
.calendar.svelte-pcimu8.thead {
  border-collapse: collapse !important;
  border-top-left-radius: 50px;
  border-top-right-radius: 50px;
}

/*Calendar Col Group*/
.calendar.svelte-pcimu8 {
  border-collapse: inherit !important;
}

/*Vertical Cell Outlines */
#calendar-container td {
	width: 12.5%;
	border: none;
	padding: 0px 0px 0px 0px !important;
	line-height: 22px;
}

/*Horizontal Cell Outlines */
#calendar-container tr {
	width: 12.5%;
  border: none;
	padding: 0px 0px 0px 0px !important;
	line-height: 22px;
}

/*Vertical Margin Adjust*/
#calendar-container .calendar{
	margin: -6px 0;
}

/*Today Button*/
#calendar-container .reset-button {
	font-size: 22px !important;
  font-weight: var(--weight-maxbold) !important;
	padding: auto;
	line-height: 1;
	text-align: center;
	color: hsl(var(--color-interactable));
}

/*Today Button Hover*/
#calendar-container .reset-button:hover {
  font-size: 22px !important;
  font-weight: var(--weight-maxbold) !important;
	background-image: repeating-linear-gradient(90deg, 
 hsl(var(--color-pink)) 5%,hsl(var(--color-red)) 15%,hsl(var(--color-orange)) 25%, 
 hsl(var(--color-yellow)) 35%,hsl(var(--color-green)) 45%,hsl(var(--color-teal)) 55%, 
 hsl(var(--color-blue)) 65%,hsl(var(--color-cyan)) 75%,hsl(var(--color-purple)) 85%, 
 hsl(var(--color-pink)) 95%);
  background-size: 1000% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: rainbow 12s linear infinite;
}

/*Previous/Next Month Button*/
.arrow.svelte-156w7na svg.svelte-156w7na {
  color: hsl(var(--color-alternate)) !important;
}

/*Previous/Next Month Button Hover*/
.arrow.svelte-156w7na svg.svelte-156w7na:hover {
  color: hsl(var(--color-hovered)) !important;
}

/*Day*/
#calendar-container .day {
  color: hsl(var(--color-text-normal));
  font-size: var(--size-text-p);
}

/*Day Current*/
.today.svelte-q3wqg9 {
  color: hsl(var(--color-confirmed)) !important;
  font-weight: var(--weight-maxbold);
}

/*Day Current Hover*/
.today.svelte-q3wqg9:hover {
  color: hsl(var(--color-text-highlight)) !important;
  font-weight: var(--weight-maxbold);
}

/*Day With Note Selected*/
.active.svelte-q3wqg9:not(:hover) {
  background-color: inherit !important;
  color: hsl(var(--color-selected)) !important;
}

/*Day Hover*/
#calendar-container .day:hover{
	background-color: hsl(var(--color-hovered));
  color: hsl(var(--color-text-highlight));
  transition: var(--anim-duration-slow);
}

/*Weekday Abbreviation Lables*/
#calendar-container th {
	padding: 6px 3px;
  border-bottom: 2px solid hsl(var(--color-content)) !important;
  border-right: none !important;
  border-left: none !important;
  border-top: none !important;
	background-color: hsl(var(--color-base-3));
  font-size: var(--size-text-h6);
}
.style-solar #calendar-container th {
  background-color: hsl(var(--color-base-2));
}

/*Week Numbers*/
td.svelte-egt0yd {
  font-size: var(--size-text-h6);
}

/* Week*/
#calendar-container .week-num {
  border-right: 2px solidhsl(var(--color-confirmed));
	background-color: hsl(var(--color-base-3));
  color: hsl(var(--color-text-normal));
  border-radius: 0 !important;
}
.style-solar #calendar-container .week-num {
  background-color: hsl(var(--color-base-2));
}

/*Week With Note Active*/
.active.svelte-egt0yd {
  background-color: hsl(var(--color-selected)) !important;
}

/* Week Hover*/
#calendar-container .week-num:hover {
	background-color: hsl(var(--color-hovered)) !important;
  color: hsl(var(--color-text-highlight));
  transition: var(--anim-duration-slow);
}

/*Dot Container*/
#calendar-container .dot-container {
	margin-top: -2px;
	margin-bottom: -1px;
}

/*Dot*/
#calendar-container .dot {
	fill: hsl(var(--color-text-faint));
}

/* Month*/
#calendar-container .month {
	font-size: 30px;
	line-height: 1;
	color: hsl(var(--color-text-bold));
  font-weight: var(--weight-bold);
  font-style: italic;
}

/* Year*/
#calendar-container .year {
	font-size: 30px;
	line-height: 1;
	color: hsl(var(--color-text-italic));
  font-weight: var(--weight-maxbold);
  font-style: italic;
}

